"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[1392],{6151:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[{"name":"CropOffset","desc":"Where a crop sits within its soil plot. Stored as plain numbers rather than a\\nCFrame so it survives datastore serialization, and relative to the soil so moving\\nthe plot carries the crops with it.","fields":[{"name":"X","lua_type":"number","desc":"Offset along the soil\'s local X axis"},{"name":"Y","lua_type":"number","desc":"Offset along the soil\'s local Z axis"},{"name":"R","lua_type":"number","desc":"Y rotation in the soil\'s local space"}],"source":{"line":33,"path":"src/Shared/Types/CropTypes.luau"}},{"name":"ProduceData","desc":"One piece of fruit hanging on a crop tree, waiting to be picked. Regular\\nsingle-harvest crops never populate this.","fields":[{"name":"produceId","lua_type":"string","desc":"Item id of the produce"},{"name":"modifier","lua_type":"ItemModifier.Modifier?","desc":"Quality/variant modifier rolled for this piece"},{"name":"scale","lua_type":"number","desc":"Size multiplier, which feeds into its value"},{"name":"creationTime","lua_type":"number","desc":"Timestamp the produce appeared"}],"source":{"line":46,"path":"src/Shared/Types/CropTypes.luau"}},{"name":"SavedCropData","desc":"One planted crop.\\n\\n`yields` and `produce` are only meaningful for seeds whose data defines\\n`cropTreeData` \u2014 those keep producing instead of being harvested once.\\n`instantlyGrown` records that the timer was skipped, so the crop reads as mature\\nregardless of `plantedAt`.","fields":[{"name":"seedItemId","lua_type":"string","desc":"Seed this was planted from; drives all growth timings"},{"name":"plantedAt","lua_type":"number","desc":"Timestamp planted; growth stage is derived from this"},{"name":"cropId","lua_type":"string","desc":"Unique id, so each planted crop can be tracked individually"},{"name":"offset","lua_type":"CropOffset","desc":"Position within the soil plot"},{"name":"scale","lua_type":"number","desc":"Size multiplier for the grown crop"},{"name":"modifier","lua_type":"ItemModifier.Modifier?","desc":"Quality/variant modifier rolled at planting"},{"name":"instantlyGrown","lua_type":"boolean?","desc":"Crop was finished early with Robux"},{"name":"yields","lua_type":"number?","desc":"Harvests taken so far, for crop trees"},{"name":"produce","lua_type":"{ ProduceData }?","desc":"Produce currently on a crop tree"}],"source":{"line":73,"path":"src/Shared/Types/CropTypes.luau"}},{"name":"SavedSoilData","desc":"A soil prop\'s slice of its saved `props` table.","fields":[{"name":"crops","lua_type":"{ SavedCropData }","desc":"Every crop planted in this soil plot"}],"source":{"line":92,"path":"src/Shared/Types/CropTypes.luau"}},{"name":"BulkCropDataItem","desc":"One line of a bulk harvest, so a whole plot can be granted in a single round trip\\nrather than one message per crop.","fields":[{"name":"cropItemId","lua_type":"string","desc":"Item id of the harvested crop"},{"name":"props","lua_type":"{ modifier: ItemModifier.Modifier?, scale: number }","desc":"Modifier and size that decide its value"}],"source":{"line":105,"path":"src/Shared/Types/CropTypes.luau"}}],"name":"CropTypes","desc":"Saved shape of planted crops and the produce they yield.\\n\\nA crop is stored as the *seed* that made it plus a `plantedAt` timestamp \u2014 growth\\nstage is recomputed from elapsed time against the seed\'s timings in\\n`ItemTypes.SeedItemData`, never persisted. That keeps crops growing while the\\nplayer is offline without anything having to tick.\\n\\nThese types live inside a soil prop\'s saved `props` table (see\\n`PropTypes.PropReplicaData`), so writing to them persists.\\n\\nCopyright (c) 2026 firebit. All rights reserved.\\nfirebit/murder-escape - proprietary and confidential.","source":{"line":17,"path":"src/Shared/Types/CropTypes.luau"}}')}}]);